  @keyframes block-rise {
    to { transform: translateY(0); }
  }
  @keyframes char-rise {
    to { transform: translateY(0); }
  }
  @media (prefers-reduced-motion: reduce) {
    .hero-headline,
    .hero-headline .char {
      animation: none;
      transform: none;
    }
