  .ss-wws-section {
    position: relative;
    height: 650vh;              /* longer runway: zoom + post-it read time */
    width: 100%;
    margin-left: calc(50% - 50vw);
    margin-right: calc(50% - 50vw);
  }

  .ss-wws-sticky {
    position: sticky;
    top: 0;                    /* full viewport coverage — GIF edge to edge, no strip */
    left: 0;
    width: 100vw;
    height: 100vh;
    overflow: hidden;
    background: #fff;
  }

  .ss-wws-gif {
    position: absolute;
    top: -2px; left: -2px;
    width: calc(100% + 4px);
    height: calc(100% + 4px);
    object-fit: cover;
    object-position: center;
    pointer-events: none;
  }

  .ss-wws-mask-wrap {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
    transform-origin: 50% 50%;   /* centered cutout, zoom from center */

  }

  .ss-wws-mask-wrap svg {
    width: 100%;
    height: 100%;
    display: block;
    overflow: visible;
  }

  /* ── Post-it layer ── */
  .ss-wws-notes {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
  }

  .ss-wws-note {
    position: absolute;
    background: #F2E6C9;                 /* warm paper */
    color: #111;                          /* black text */
    padding: 1.4rem 1.4rem 1.6rem;
    width: clamp(190px, 15vw, 250px);     /* wider — matches mockup */
    min-height: clamp(240px, 19vw, 320px);  /* taller — portrait like mockup */
    box-shadow: 0 14px 30px rgba(0,0,0,0.22);
    font-family: 'Inter Tight', var(--body-font-font-family, sans-serif);
    font-weight: 600;
    font-size: clamp(1.15rem, 1.4vw, 1.5rem);
    line-height: 1.05;
    letter-spacing: -0.01em;
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    justify-content: flex-end;          /* push text toward the bottom */
    /* start off to the right + invisible; JS reveals */
    opacity: 0;
    transform: translateX(80px);
    backface-visibility: hidden;
  }

  /* the little square tab in the corner */
  .ss-wws-note::before {
    content: "";
    position: absolute;
    top: 1.1rem;
    left: 1.1rem;
    width: 11px;
    height: 11px;
    background: #1f3d2b;
  }

  .ss-wws-note p { margin: 0; }   /* flex pushes the text to the bottom */

  .ss-wws-hint {
    position: absolute;
    top: 62%;                 /* below the centered text */
    bottom: auto;
    left: 50%;
    transform: translateX(-50%);
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.5rem;
    pointer-events: none;
    z-index: 10;
    transition: opacity 0.3s ease;
  }

  .ss-wws-hint span {
    font-family: 'Inter Tight', var(--body-font-font-family, sans-serif);
    font-weight: 600;
    font-size: 0.62rem;
    letter-spacing: 0.2em;
    text-transform: uppercase;
    color: #000;
  }

  .ss-wws-hint-line {
    width: 1px;
    height: 2rem;
    background: #000;
    animation: ss-wws-drop 1.6s ease-in-out infinite;
  }

  @keyframes ss-wws-drop {
    0%   { transform: scaleY(1);   opacity: 0.4; }
    50%  { transform: scaleY(0.3); opacity: 1;   }
    100% { transform: scaleY(1);   opacity: 0.4; }
  }

  /* ── Mobile: stack the notes so they stay readable ── */
  @media (max-width: 768px) {
    .ss-wws-note {
      width: 40vw;
      min-height: 40vw;
      font-size: 0.78rem;
      padding: 1rem;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .ss-wws-mask-wrap, .ss-wws-note { transition: none !important; }
    .ss-wws-hint-line { animation: none !important; }
  }




